// Some portions generated by Codex
package org.eclipse.rdf4j.repository.sparql.federation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

import java.net.URI;

import org.eclipse.rdf4j.common.net.RemoteResourceAccessPolicy;
import org.eclipse.rdf4j.http.client.SharedHttpClientSessionManager;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.junit.jupiter.api.Test;

class SPARQLServiceResolverSecurityTest {

	@Test
	void rejectsPrivateServiceBeforeCreatingFederatedService() {
		SPARQLServiceResolver resolver = new SPARQLServiceResolver();
		try {
			assertThatThrownBy(() -> resolver.getService("http://127.0.0.1/sparql"))
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining("Remote resource access denied");
		} finally {
			resolver.shutDown();
		}
	}

	@Test
	void injectedPolicyCoversServiceAndOwnedHttpClient() throws Exception {
		RemoteResourceAccessPolicy policy = mock(RemoteResourceAccessPolicy.class);
		SPARQLServiceResolver resolver = SPARQLServiceResolver.class
				.getConstructor(RemoteResourceAccessPolicy.class)
				.newInstance(policy);
		URI endpoint = URI.create("http://127.0.0.1/sparql");
		try {
			resolver.getService(endpoint.toString());

			verify(policy).checkInitial(endpoint);
			SharedHttpClientSessionManager manager = (SharedHttpClientSessionManager) resolver
					.getHttpClientSessionManager();
			assertThat(manager.getDefaultHttpClientConfig().getRemoteResourceAccessPolicy()).isSameAs(policy);
		} finally {
			resolver.shutDown();
		}
	}
}
